**`src/config.ts`**
```ts
import "dotenv/config";

function required(name: string): string {
  const v = process.env[name];
  if (!v || v.startsWith("__YOUR_")) {
    throw new Error(`Missing env var ${name}. Copy .env.example to .env and fill it in.`);
  }
  return v;
}

export const config = {
  supabaseUrl: required("SUPABASE_URL"),
  supabaseAnonKey: required("SUPABASE_ANON_KEY"),
  // Service-role is optional at import time; only required by the admin client.
  supabaseServiceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY ?? "",
  storageBucket: process.env.SUPABASE_STORAGE_BUCKET ?? "customer-files",
};
```

**`src/lib/supabaseClient.ts`**
```ts
import { createClient, SupabaseClient } from "@supabase/supabase-js";
import { config } from "../config.js";

// Public client — uses the anon key. Safe for browser / untrusted contexts.
export const supabase: SupabaseClient = createClient(
  config.supabaseUrl,
  config.supabaseAnonKey,
  { auth: { persistSession: true, autoRefreshToken: true } }
);

// Admin client — uses the service-role key. BACKEND ONLY. Never import in client code.
export function getAdminClient(): SupabaseClient {
  if (!config.supabaseServiceRoleKey) {
    throw new Error("SUPABASE_SERVICE_ROLE_KEY is not set — admin client unavailable.");
  }
  return createClient(config.supabaseUrl, config.supabaseServiceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}
```

**`src/auth/auth.ts`**
```ts
import { supabase } from "../lib/supabaseClient.js";
import type { Session, User } from "@supabase/supabase-js";

export async function signUp(email: string, password: string): Promise<User | null> {
  const { data, error } = await supabase.auth.signUp({ email, password });
  if (error) throw error;
  return data.user;
}

export async function signIn(email: string, password: string): Promise<Session | null> {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) throw error;
  return data.session;
}

export async function signOut(): Promise<void> {
  const { error } = await supabase.auth.signOut();
  if (error) throw error;
}

export async function getSession(): Promise<Session | null> {
  const { data, error } = await supabase.auth.getSession();
  if (error) throw error;
  return data.session;
}

// Subscribe to auth changes; returns an unsubscribe function.
export function onAuthStateChange(
  cb: (event: string, session: Session | null) => void
): () => void {
  const { data } = supabase.auth.onAuthStateChange((event, session) => cb(event, session));
  return () => data.subscription.unsubscribe();
}
```

**`src/storage/storage.ts`**
```ts
import { supabase, getAdminClient } from "../lib/supabaseClient.js";
import { config } from "../config.js";

// Create the bucket if it doesn't exist (admin/service-role only).
export async function ensureBucket(
  name: string = config.storageBucket,
  isPublic = false
): Promise<void> {
  const admin = getAdminClient();
  const { data } = await admin.storage.getBucket(name);
  if (!data) {
    const { error } = await admin.storage.createBucket(name, { public: isPublic });
    if (error) throw error;
  }
}

export async function upload(path: string, file: Blob | ArrayBuffer | Buffer, bucket = config.storageBucket) {
  const { data, error } = await supabase.storage.from(bucket).upload(path, file, { upsert: true });
  if (error) throw error;
  return data;
}

export async function download(path: string, bucket = config.storageBucket): Promise<Blob> {
  const { data, error } = await supabase.storage.from(bucket).download(path);
  if (error) throw error;
  return data;
}

export async function list(prefix = "", bucket = config.storageBucket) {
  const { data, error } = await supabase.storage.from(bucket).list(prefix);
  if (error) throw error;
  return data;
}

export async function remove(paths: string[], bucket = config.storageBucket) {
  const { data, error } = await supabase.storage.from(bucket).remove(paths);
  if (error) throw error;
  return data;
}

export function publicUrl(path: string, bucket = config.storageBucket): string {
  return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl;
}
```

